import{_ as r,a0 as s,w as i,s as d,ao as p,I as a,x as u,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"Linux有問必答：如何更新過期版本的Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何更新過期版本的Ubuntu | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何更新過期版本的Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何更新過期版本的Ubuntu | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 Linux FAQs with Answers--How to fix '404 Not Found' error with 'apt-get update' on old Ubuntu","title":"Linux有問必答：如何更新過期版本的Ubuntu","tag":"201506","desc":""},"relativePath":"201506/20150518 Linux FAQs with Answers--How to fix '404 Not Found' error with 'apt-get update' on old Ubuntu.md","filePath":"[post].md"}`),l={name:"201506/20150518 Linux FAQs with Answers--How to fix '404 Not Found' error with 'apt-get update' on old Ubuntu.md"};function b(m,t,x,f,g,c){const n=s("Link");return i(),d("div",null,[t[13]||(t[13]=p(`<h1 id="linux有問必答-如何更新過期版本的ubuntu" tabindex="-1">Linux有問必答：如何更新過期版本的Ubuntu <a class="header-anchor" href="#linux有問必答-如何更新過期版本的ubuntu" aria-label="Permalink to “Linux有問必答：如何更新過期版本的Ubuntu”">​</a></h1><blockquote><p><strong>問題</strong>： 我的PC上安裝了舊版的Ubuntu 13.04（急切的浣熊）。當我在上面運行“sudo apt-get update”時，它丟給了我一大堆“404 Not Found”錯誤，結果是我不能使用apt-get或aptitude來安裝或更新任何軟件包了。由於該錯誤的原因，我甚至不能將它升級到更新的版本。我怎樣才能修復這個問題啊？</p></blockquote><p><img src="https://farm6.staticflickr.com/5460/17634085636_996b2a8ab5_b.jpg" alt=""></p><p>每個Ubuntu版本都有生命結束週期（EOL）時間；常規的Ubuntu發行版提供18個月的支持，而LTS（長期支持）版本則長達3年（服務器版本）和5年（桌面版本）。當某個Ubuntu版本達到生命結束週期時，其倉庫就不能再訪問了，你也不能再從Canonical獲取任何維護更新和安全補丁。在撰寫本文時，Ubuntu 13.04（急切的浣熊）已經達到了它的生命結束週期。</p><p>如果你所使用的Ubuntu系統已經被結束生命週期，你就會從apt-get或aptitude得到以下404錯誤，因為它的倉庫已經被遺棄了。</p><pre><code>W: Failed to fetch http://us.archive.ubuntu.com/ubuntu/dists/raring-backports/multiverse/binary-i386/Packages  404  Not Found [IP: 91.189.91.13 80]

W: Failed to fetch http://extras.ubuntu.com/ubuntu/dists/raring/main/binary-amd64/Packages  404  Not Found

W: Failed to fetch http://security.ubuntu.com/ubuntu/dists/raring-security/universe/binary-i386/Packages  404  Not Found [IP: 91.189.88.149 80]

E: Some index files failed to download. They have been ignored, or old ones used instead
</code></pre><p>對於那些還在使用舊版本Ubuntu的用户，Canonical維護了一個old-releases.ubuntu.com的網站，這裏包含了結束生命週期的倉庫歸檔。因此，當Canonical對你安裝的Ubuntu版本結束支持時，你需要將倉庫切換到old-releases.ubuntu.com（除非你在結束生命週期之前想要升級）。</p><p>這裏，通過切換到舊版本倉庫提供了一個快速修復“404 Not Found”錯誤的便捷方式。</p><p>首先，使用old-releases倉庫替換main/security倉庫，就像下面這樣。</p><pre><code>$ sudo sed -i -r &#39;s/([a-z]{2}\\.)?archive.ubuntu.com/old-releases.ubuntu.com/g&#39; /etc/apt/sources.list
$ sudo sed -i -r &#39;s/security.ubuntu.com/old-releases.ubuntu.com/g&#39; /etc/apt/sources.list
</code></pre><p>然後，使用文本編輯器打開/etc/apt/sources.list，並查找extras.ubuntu.com。該倉庫也不再支持Ubuntu 13.04了，所以你需要使用“#”號將extras.ubuntu.com註釋掉。</p><pre><code>#deb http://extras.ubuntu.com/ubuntu raring main
#deb-src http://extras.ubuntu.com/ubuntu raring main
</code></pre><p>現在，你應該可以在舊版不受支持的Ubuntu上安裝或更新軟件包了。</p><hr>`,14)),a("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/404-not-found-error-apt-get-update-ubuntu.html"},{default:o(()=>[...t[0]||(t[0]=[u("http://ask.xmodulo.com/404-not-found-error-apt-get-update-ubuntu.html",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=u("作者：",-1)),e(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...t[2]||(t[2]=[u("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=u(" 譯者：",-1)),e(n,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[3]||(t[3]=[u("GOLinux",-1)])]),_:1}),t[7]||(t[7]=u(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[u("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[u("LCTT",-1)])]),_:1}),t[11]||(t[11]=u(" 原創翻譯，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[u("Linux中國",-1)])]),_:1}),t[12]||(t[12]=u(" 榮譽推出",-1))])])}const h=r(l,[["render",b]]);export{T as __pageData,h as default};
